1681	type displayResponseState struct {
1682		lineLength int
1683		wordBuffer string
1684	}
1685	
1686	func displayResponse(content string, wordWrap bool, state *displayResponseState) {
1687		termWidth, _, _ := term.GetSize(int(os.Stdout.Fd()))
1688		if termWidth == 0 {
1689			termWidth = 80
1690		}
1691		if wordWrap && termWidth >= 10 {
1692			for _, ch := range content {
1693				if state.lineLength+1 > termWidth-5 {
1694					if runewidth.StringWidth(state.wordBuffer) > termWidth-10 {
1695						fmt.Printf("%s%c", state.wordBuffer, ch)
1696						state.wordBuffer = ""
1697						state.lineLength = 0
1698						continue
1699					}
1700	
1701					// backtrack the length of the last word and clear to the end of the line
1702					a := runewidth.StringWidth(state.wordBuffer)
1703					if a > 0 {
1704						fmt.Printf("\x1b[%dD", a)
1705					}
1706					fmt.Printf("\x1b[K\n")
1707					fmt.Printf("%s%c", state.wordBuffer, ch)
1708					chWidth := runewidth.RuneWidth(ch)
1709	
1710					state.lineLength = runewidth.StringWidth(state.wordBuffer) + chWidth
1711				} else {
1712					fmt.Print(string(ch))
1713					state.lineLength += runewidth.RuneWidth(ch)
1714					if runewidth.RuneWidth(ch) >= 2 {
1715						state.wordBuffer = ""
1716						continue
1717					}
1718	
1719					switch ch {
1720					case ' ', '\t':
1721						state.wordBuffer = ""
1722					case '\n', '\r':
1723						state.lineLength = 0
1724						state.wordBuffer = ""
1725					default:
1726						state.wordBuffer += string(ch)
1727					}
1728				}
1729			}
1730		} else {
1731			fmt.Printf("%s%s", state.wordBuffer, content)
1732			if len(state.wordBuffer) > 0 {
1733				state.wordBuffer = ""
1734			}
1735		}
1736	}
