544		p := progress.NewProgress(os.Stderr)
545		defer p.StopAndClear()
546	
547		spinner := progress.NewSpinner("")
548		p.Add("", spinner)
549	
550		client, err := api.ClientFromEnvironment()
551		if err != nil {
552			return err
553		}
554	
555		requestedCloud := modelref.HasExplicitCloudSource(opts.Model)
556	
557		if info, err := client.Show(cmd.Context(), &api.ShowRequest{Model: opts.Model}); err != nil {
558			return err
559		} else if info.RemoteHost != "" || requestedCloud {
560			// Cloud model, no need to load/unload
561	
562			isCloud := requestedCloud || strings.HasPrefix(info.RemoteHost, "https://ollama.com")
563	
564			// Check if user is signed in for ollama.com cloud models
565			if isCloud {
566				if _, err := client.Whoami(cmd.Context()); err != nil {
567					return err
568				}
569			}
570	
571			if opts.ShowConnect {
572				p.StopAndClear()
573				remoteModel := info.RemoteModel
574				if remoteModel == "" {
575					remoteModel = opts.Model
576				}
577				if isCloud {
578					fmt.Fprintf(os.Stderr, "Connecting to '%s' on 'ollama.com' ⚡\n", remoteModel)
579				} else {
580					fmt.Fprintf(os.Stderr, "Connecting to '%s' on '%s'\n", remoteModel, info.RemoteHost)
581				}
582			}
583	
584			return nil
585		}
586	
587		req := &api.GenerateRequest{
588			Model:     opts.Model,
589			KeepAlive: opts.KeepAlive,
590	
591			// pass Think here so we fail before getting to the chat prompt if the model doesn't support it
592			Think: opts.Think,
593		}
594	
595		return client.Generate(cmd.Context(), req, func(r api.GenerateResponse) error {
596			return nil
597		})
598	}
