600	func StopHandler(cmd *cobra.Command, args []string) error {
601		opts := &runOptions{
602			Model:     args[0],
603			KeepAlive: &api.Duration{Duration: 0},
604		}
605		if err := loadOrUnloadModel(cmd, opts); err != nil {
606			if strings.Contains(err.Error(), "not found") {
607				return fmt.Errorf("couldn't find model \"%s\" to stop", args[0])
608			}
609			return err
610		}
611		return nil
612	}
