614	func generateEmbedding(cmd *cobra.Command, modelName, input string, keepAlive *api.Duration, truncate *bool, dimensions int) error {
615		client, err := api.ClientFromEnvironment()
616		if err != nil {
617			return err
618		}
619	
620		req := &api.EmbedRequest{
621			Model: modelName,
622			Input: input,
623		}
624		if keepAlive != nil {
625			req.KeepAlive = keepAlive
626		}
627		if truncate != nil {
628			req.Truncate = truncate
629		}
630		if dimensions > 0 {
631			req.Dimensions = dimensions
632		}
633	
634		resp, err := client.Embed(cmd.Context(), req)
635		if err != nil {
636			return err
637		}
638	
639		if len(resp.Embeddings) == 0 {
640			return errors.New("no embeddings returned")
641		}
642	
643		output, err := json.Marshal(resp.Embeddings[0])
644		if err != nil {
645			return err
646		}
647		fmt.Println(string(output))
648	
649		return nil
650	}
