250	func (s *Server) GenerateHandler(c *gin.Context) {
251		checkpointStart := time.Now()
252		var req api.GenerateRequest
253		if err := c.ShouldBindJSON(&req); errors.Is(err, io.EOF) {
254			c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": "missing request body"})
255			return
256		} else if err != nil {
257			c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": err.Error()})
258			return
259		}
260	
261		if req.TopLogprobs < 0 || req.TopLogprobs > 20 {
262			c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": "top_logprobs must be between 0 and 20"})
263			return
264		}
265	
266		modelRef, err := parseAndValidateModelRef(req.Model)
267		if err != nil {
268			writeModelRefParseError(c, err, http.StatusNotFound, fmt.Sprintf("model '%s' not found", req.Model))
269			return
270		}
271	
272		if modelRef.Source == modelSourceCloud {
273			// TODO(drifkin): evaluate an `/api/*` passthrough for cloud where the
274			// original body (modulo model name normalization) is sent to cloud.
275			req.Model = modelRef.Base
276			proxyCloudJSONRequest(c, req, cloudErrRemoteInferenceUnavailable)
277			return
278		}
279	
280		name := modelRef.Name
281	
282		// We cannot currently consolidate this into GetModel because all we'll
283		// induce infinite recursion given the current code structure.
284		name, err = getExistingName(name)
285		if err != nil {
286			c.JSON(http.StatusNotFound, gin.H{"error": fmt.Sprintf("model '%s' not found", req.Model)})
287			return
288		}
289	
290		m, err := GetModel(name.String())
291		if err != nil {
292			switch {
293			case errors.Is(err, fs.ErrNotExist):
294				c.JSON(http.StatusNotFound, gin.H{"error": fmt.Sprintf("model '%s' not found", req.Model)})
295			case err.Error() == errtypes.InvalidModelNameErrMsg:
296				c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
297			default:
298				c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
299			}
300			return
301		}
302	
303		if req.TopLogprobs < 0 || req.TopLogprobs > 20 {
304			c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": "top_logprobs must be between 0 and 20"})
305			return
306		}
307	
308		if modelRef.Source == modelSourceLocal && m.Config.RemoteHost != "" && m.Config.RemoteModel != "" {
309			c.JSON(http.StatusNotFound, gin.H{"error": fmt.Sprintf("model '%s' not found", req.Model)})
310			return
311		}
312	
313		if m.Config.RemoteHost != "" && m.Config.RemoteModel != "" {
314			if disabled, _ := internalcloud.Status(); disabled {
315				c.JSON(http.StatusForbidden, gin.H{"error": internalcloud.DisabledError(cloudErrRemoteInferenceUnavailable)})
316				return
317			}
318	
319			origModel := req.Model
320	
321			remoteURL, err := url.Parse(m.Config.RemoteHost)
322			if err != nil {
323				c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
324				return
325			}
326	
327			if !slices.Contains(envconfig.Remotes(), remoteURL.Hostname()) {
328				slog.Info("remote model", "remotes", envconfig.Remotes(), "remoteURL", m.Config.RemoteHost, "hostname", remoteURL.Hostname())
329				c.JSON(http.StatusBadRequest, gin.H{"error": "this server cannot run this remote model"})
330				return
331			}
332	
333			req.Model = m.Config.RemoteModel
334	
335			if req.Template == "" && m.Template.String() != "" {
336				req.Template = m.Template.String()
337			}
338	
339			if req.Options == nil {
340				req.Options = map[string]any{}
341			}
342	
343			for k, v := range m.Options {
344				if _, ok := req.Options[k]; !ok {
345					req.Options[k] = v
346				}
347			}
348	
349			// update the system prompt from the model if one isn't already specified
