358			contentType := "application/x-ndjson"
359			if req.Stream != nil && !*req.Stream {
360				contentType = "application/json; charset=utf-8"
361			}
362			c.Header("Content-Type", contentType)
363	
364			fn := func(resp api.GenerateResponse) error {
365				resp.Model = origModel
366				resp.RemoteModel = m.Config.RemoteModel
367				resp.RemoteHost = m.Config.RemoteHost
368	
369				data, err := json.Marshal(resp)
370				if err != nil {
371					return err
372				}
373	
374				if _, err = c.Writer.Write(append(data, '\n')); err != nil {
375					return err
376				}
377				c.Writer.Flush()
378				return nil
379			}
380	
381			client := api.NewClient(remoteURL, http.DefaultClient)
382			err = client.Generate(c, &req, fn)
383			if err != nil {
384				var authError api.AuthorizationError
385				if errors.As(err, &authError) {
386					sURL, sErr := signinURL()
387					if sErr != nil {
388						slog.Error(sErr.Error())
389						c.JSON(http.StatusInternalServerError, gin.H{"error": "error getting authorization details"})
390						return
391					}
392	
393					c.JSON(authError.StatusCode, gin.H{"error": "unauthorized", "signin_url": sURL})
