399					return
400				}
401				c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
402				return
403			}
404	
405			return
406		}
407	
408		// expire the runner if unload is requested (empty prompt, keep alive is 0)
409		if req.Prompt == "" && req.KeepAlive != nil && req.KeepAlive.Duration == 0 {
410			s.sched.expireRunner(m)
411	
412			c.JSON(http.StatusOK, api.GenerateResponse{
413				Model:      req.Model,
414				CreatedAt:  time.Now().UTC(),
415				Response:   "",
416				Done:       true,
417				DoneReason: "unload",
418			})
419			return
420		}
421	
422		if slices.Contains(m.Capabilities(), model.CapabilityImage) {
